/**
 * Who launched which cloud agent. The tools authenticate with the serve
 * host's one Cursor API key, so the host itself must keep every session's
 * cloud agents bound to the principal that launched them: status and
 * follow-ups only reach agents recorded here for the same principal, and
 * the fleet listing is that principal's records, by default narrowed to the
 * session that launched them.
 */
import { randomUUID } from "node:crypto";
import * as z from "zod/v4";
const PREFIX = "cloud-agents";
const fleetSchema = z.array(z.object({
    agentId: z.string(),
    name: z.string().optional(),
    launchedAt: z.string(),
    sessionId: z.string().optional(),
}));
const ownerSchema = z.object({
    principal: z.string(),
    /** The launch registered the status webhook; absent on launches before it existed. */
    webhook: z.literal(true).optional(),
    /** Set while no launch of the claimed id has returned; one value per claim. */
    pending: z.string().optional(),
    /** When the pending claim was written, in ms since the epoch. */
    claimedAt: z.number().optional(),
});
// `host.kv` has no compare-and-swap, and a model that launches two agents in
// one turn calls this tool in parallel. Chain the index read-modify-write per
// principal so neither launch overwrites the other's entry.
const indexWrites = new Map();
function withIndexLock(key, task) {
    const run = (indexWrites.get(key) ?? Promise.resolve()).then(task, task);
    indexWrites.set(key, run);
    return run.finally(() => {
        if (indexWrites.get(key) === run) {
            indexWrites.delete(key);
        }
    });
}
/** Unauthenticated sessions (local dev, direct calls) share one principal. */
export function principalOf(ctx) {
    const auth = ctx.session.auth;
    return auth === null ? "anonymous" : `${auth.principalType}:${auth.principalId}`;
}
export async function recordLaunch(ctx, agentId, name, launch) {
    const principal = principalOf(ctx);
    const entry = {
        agentId,
        name,
        launchedAt: new Date().toISOString(),
        sessionId: ctx.session.id,
    };
    await ctx.host.kv.put(ownerKey(agentId), launch.webhook ? { principal, webhook: true } : { principal });
    await withIndexLock(fleetKey(principal), async () => {
        const fleet = await listFleet(ctx);
        await ctx.host.kv.put(fleetKey(principal), [
            entry,
            ...fleet.filter((earlier) => earlier.agentId !== agentId),
        ]);
    });
}
/**
 * Bind an agent id to this principal before its launch, so that a retry of
 * the same launch can take the agent the first attempt created. Refuses an
 * id that another principal holds. `earlier` is true when this principal
 * held the id before this call. `claimedAt` is set while no launch of the id
 * has returned, so an agent the API created before it is not this claim's.
 */
export async function claimAgentId(ctx, agentId) {
    const key = ownerKey(agentId);
    const stored = await ctx.host.kv.get(key);
    let pending;
    let claimedAt;
    if (stored === undefined) {
        pending = randomUUID();
        claimedAt = Date.now();
        await ctx.host.kv.put(key, { principal: principalOf(ctx), pending, claimedAt });
    }
    else {
        const owner = ownerOf(ctx, agentId, stored);
        if (owner.pending === undefined || owner.claimedAt === undefined) {
            return {
                earlier: true,
                webhook: owner.webhook === true,
                claimedAt: undefined,
                release: async () => { },
            };
        }
        pending = owner.pending;
        claimedAt = owner.claimedAt;
    }
    return {
        earlier: stored !== undefined,
        webhook: false,
        claimedAt,
        // Leave the record when a parallel launch of the same id replaced the claim.
        release: async () => {
            const current = ownerSchema.safeParse(await ctx.host.kv.get(key));
            if (current.success && current.data.pending === pending) {
                await ctx.host.kv.delete(key);
            }
        },
    };
}
/**
 * Refuse agents launched by another principal, or not through the extension.
 * A claim whose launch never returned does not count.
 * Resolves with whether the launch registered the status webhook.
 */
export async function assertOwned(ctx, agentId) {
    const owner = ownerOf(ctx, agentId, await ctx.host.kv.get(ownerKey(agentId)));
    if (owner.pending !== undefined) {
        throw notLaunchedHere(agentId);
    }
    return { webhook: owner.webhook === true };
}
/**
 * Turn a pending claim on `agentId` into a launch with the status webhook.
 * Only a signed status webhook may call this: it names only agents the
 * platform launched with this deployment's webhook, so the launch whose reply
 * was lost created the agent. Any other record is left as it is.
 */
export async function adoptPendingLaunch(kv, agentId) {
    const key = ownerKey(agentId);
    const owner = ownerSchema.safeParse(await kv.get(key));
    if (owner.success && owner.data.pending !== undefined) {
        await kv.put(key, { principal: owner.data.principal, webhook: true });
    }
}
function ownerOf(ctx, agentId, stored) {
    const owner = ownerSchema.safeParse(stored);
    if (!owner.success || owner.data.principal !== principalOf(ctx)) {
        throw notLaunchedHere(agentId);
    }
    return owner.data;
}
function notLaunchedHere(agentId) {
    return new Error(`Agent ${agentId} was not launched through this extension by this principal; only your own launches can be read or steered.`);
}
function ownerKey(agentId) {
    return `${PREFIX}/agents/${agentId}`;
}
/** The caller's launches, newest first: this session's, or every session's. */
export async function listFleet(ctx, scope = "all") {
    const fleet = fleetSchema.safeParse(await ctx.host.kv.get(fleetKey(principalOf(ctx))));
    const entries = fleet.success ? fleet.data : [];
    return scope === "all" ? entries : entries.filter((entry) => entry.sessionId === ctx.session.id);
}
function fleetKey(principal) {
    return `${PREFIX}/principals/${encodeURIComponent(principal)}`;
}
